"""Self-contained Chinese report: text-integrated BP, fixed fusion, Astra."""
import base64,csv,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'reports/v7_text';OUT=ROOT/'runs/v7_text'
load=lambda p:json.loads(p.read_text())
s=load(R/'summary.json');C=load(R/'costs.json');Q=load(R/'quality_checks.json');F=load(OUT/'frozen_manifest.json');A=load(OUT/'assignments.json');ci=load(R/'paired_user_intervals.json')
rows=list(csv.DictReader((R/'per_case.csv').open()))
def num(a,m,k='ndcg@10'):return s['conditions'][a][m][k]
def pct(a,b):return 100*(a/b-1)
def table(headers,body):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in body)+'</tbody></table></div><p class="swipe">↔ 表格可左右滑动</p>'
def image(name):return '<figure><img alt="无文本、正确文本、打乱文本及 Astra 文本读取对照" src="data:image/png;base64,'+base64.b64encode((R/name).read_bytes()).decode()+'"></figure>'
def interval(name):
 c=ci[name];return f'[{c["lower95"]:+.5f}, {c["upper95"]:+.5f}]'
primary=table(['输入设置','BP','固定 SVD＋BP','Astra 修改'],[[name]+[f'{num(access,m):.5f}' for m in ('bp','fixed_simple','astra')] for name,access in [('无文本','none'),('含文本，Astra 同时可读标题和简介','full_text')]])
recall=table(['输入设置','BP','固定 SVD＋BP','Astra 修改'],[[name]+[f'{num(access,m,"recall@10"):.5f}' for m in ('bp','fixed_simple','astra')] for name,access in [('无文本','none'),('含文本且可读原文','full_text')]])
extra=table(['在同一含文本 BP 上的 Astra 输入','平均 NDCG@10','平均 Recall@10'],[['仅有数值文本向量',f'{num("numeric_text","astra"):.5f}',f'{num("numeric_text","astra","recall@10"):.5f}'],['另有可读标题和简介',f'{num("full_text","astra"):.5f}',f'{num("full_text","astra","recall@10"):.5f}']])
controls=table(['含文本模型的方案','NDCG@10','Recall@10'],[[label,f'{num("full_text",method):.5f}',f'{num("full_text",method,"recall@10"):.5f}'] for method,label in [('bp','BP'),('fixed_simple','固定融合：按预定验证规则可退回 BP'),('fixed_simple_raw','固定融合：强制执行原始规则'),('tuned_simple_8','八候选融合：按验证集选，含 BP 退回'),('simple_calibration_8','探索性八候选数值校准：含 BP 退回'),('astra','Astra：可看权重、训练集、向量和原文')]])
per=[]
accessnames={'none':'无文本','numeric_text':'含文本，仅数值','full_text':'含文本，可读原文'}
for key,a in A.items():
 rr={r['method']:r for r in rows if r['case']==key};chosen=F['choices'][key]['astra']
 per.append([key,a['seed'],a['replicate']+1,accessnames[a['access']],f'{float(rr["bp"]["ndcg@10"]):.5f}',f'{float(rr["fixed_simple"]["ndcg@10"]):.5f}',f'{float(rr["astra"]["ndcg@10"]):.5f}',chosen['id'] if chosen else '保留 BP'])
per=table(['编号','训练种子','编辑重复','Astra 输入','BP','固定融合','Astra','验证集选中的修改'],per)
changes=table(['案例','实际选中的修改','测试 NDCG：BP → Astra'],[
 ['case01','按训练正反馈次数，略微降低热门电影的基础分','0.11817 → 0.11830'],
 ['case05','把原电影基础分向训练热门度先验靠拢一半','0.11373 → 0.11556'],
 ['case06','把学到的文本映射矩阵放大 25%','0.11373 → 0.11375'],
 ['case08','没有方案通过验证选择，保留原 BP','0.11817 → 0.11817'],
 ['case09','一次公式计算的用户向量调整，搭配文本映射放大 15%','0.11208 → 0.11399'],
 ['case15','把学到的文本映射矩阵放大 30%','0.11208 → 0.11526']])
flow='''<div class="flow"><div class="node fixed">电影标题＋公开简介<br><small>已有 Llama-3 编码</small><b>4,096 个数</b></div><span>→</span><div class="node fixed">固定压缩、归一化<br><small>不使用用户评分</small><b>64 个数</b></div><span>→</span><div class="node learned">可训练的映射 W<br><small>BP 学习，也可供 Astra 修改</small><b>16 个文本相关数值</b></div></div><div class="flow bottom"><div class="node learned">电影 ID 向量<br><b>16 个数</b></div><span>＋</span><div class="node learned">文本相关数值<br><b>16 个数</b></div><span>→</span><div class="node learned">合成的电影向量<br><small>与用户 16 维向量相乘求和</small><b>得到推荐分数</b></div></div>'''
usage=''
if (R/'goal_usage.json').exists():
 u=load(R/'goal_usage.json');usage=f'完成时目标工具记录约 {u["goal_tool_reported_tokens_used_at_completion"]:,} tokens、{u["goal_tool_reported_elapsed_seconds"]/60:.1f} 分钟；它不是逐调用账单。'
body=f'''<header><p class="eyebrow">WSP4Rec · 文本实验 v7 · 2026-11-08</p><h1>文本改善了平均结果，<br>Astra 的增益仍有限。</h1><p class="lead">已把既有 Llama-3 电影简介向量接入 BP 训练，并让 Astra 同时读取权重、训练交互、电影标题和简介。含文本 Astra 的平均 NDCG 为 <strong>{num('full_text','astra'):.5f}</strong>，略高于含文本 BP 的 {num('full_text','bp'):.5f}，仍低于固定融合的 {num('full_text','fixed_simple'):.5f}。</p></header>
<section><h2>先看用户要求的三种结果</h2><p>下面为测试 NDCG@10，越高越好。使用相同电影子集和数据划分，重新训练三个种子的 BP；Astra 每个检查点独立重复两次，先平均两次编辑结果，再平均三个种子。</p>{primary}<p class="note">固定融合采用事先规定的“验证集不优于 BP 就保留 BP”策略，Astra 也遵循同一退回规则。若始终执行固定融合、不退回 BP，含文本得分为 <strong>{num('full_text','fixed_simple_raw'):.5f}</strong>。这两种固定结果都报告，不根据测试结果重新选主方法。</p>{image('text_comparison.png')}<details><summary>查看 Recall@10</summary>{recall}</details></section>
<section><h2>这次文本确实进入了推荐模型</h2><p>沿用 943 位用户、1,568 部电影、77,573 条训练交互；验证 9,691 条、测试 10,181 条。缓存向量实际编码的是<strong>标题＋公开简介</strong>，不是纯简介。全部向量行与电影 ID、原始 1,682 行缓存的子集逐一核对，无需重新运行 Llama。</p>{flow}<p>灰色部分固定，绿色部分由 BP 学习；Astra 可以修改已有的用户向量、电影 ID 向量、文本映射矩阵和基础分，不能修改缓存文本向量或数据。这个模型的打分方式是：用户向量 ×（电影 ID 向量＋文本映射结果），再加基础分。因此，文本参与每次推荐打分，映射矩阵 W 也在 BP 中训练；这不是仅供编辑器阅读的附加材料。</p><p>为了保持规模较小，4,096 维缓存通过固定 PCA 压缩到 64 维，保留约 {C['pca_preprocessing']['explained_variance_fraction']*100:.1f}% 的中心化总方差。PCA 只使用电影内容向量，不使用训练、验证或测试评分；电影目录整体的内容可见属于明确的目录级信息设置。Llama-3 本身未微调。</p><p>模型保留自由的电影 ID 向量，因此形式上的打分能力仍属于矩阵分解；文本改变共享信息、正则化和优化方式，不能把多出文本分支称为新模型理论。W 非零也不能单独证明电影语义有效，所以额外训练了“打乱电影与文本向量对应关系”的同结构对照。</p></section>
<section><h2>把文本的两种作用分开看</h2><p><strong>一，给 BP 文本特征。</strong>无文本 BP 为 {num('none','bp'):.5f}，正确对应文本 BP 为 {num('full_text','bp'):.5f}，平均增加 {pct(num('full_text','bp'),num('none','bp')):.2f}%。但只有两个训练种子提高，seed43 略降；条件用户配对差值区间为 {interval('text_bp_minus_none_bp')}，略跨零，不能称为已经证实稳定提升。</p><p>打乱文本对应关系的 BP 为 {s['bp_only_shuffled_text']['ndcg@10']:.5f}。正确文本优于打乱文本的平均差值为 +{ci['text_bp_minus_shuffled_bp']['mean_delta']:.5f}，条件区间 {interval('text_bp_minus_shuffled_bp')}。这支持电影与内容的正确对应关系确实有用，不能把收益只解释为多了参数；它也不等于证明具体情节推理能力。</p><p><strong>二，额外让 Astra 阅读原文。</strong>以下两组收到完全相同的含文本 BP 权重、训练交互、64 维输入和原始 4,096 维数值向量；区别是是否还能读取每部电影的标题和简介。</p>{extra}<p>额外提供可读原文的平均增量为 +{ci['full_text_astra_minus_numeric_text_astra']['mean_delta']:.5f}，区间 {interval('full_text_astra_minus_numeric_text_astra')}；Astra 相对同一含文本 BP 的平均增量为 +{ci['full_text_astra_minus_text_bp']['mean_delta']:.5f}，区间 {interval('full_text_astra_minus_text_bp')}。两者均跨零，当前只能说有小幅正向均值，不能确认可靠的额外文本收益。全文组相对数值组的差异主要来自 seed42。</p><p class="note">所有区间都是固定这批模型、编辑轨迹和历史划分后，对用户重采样得到的条件区间。它们不是训练种子或 Astra 总体可靠性的置信区间；三种种子、每组两次编辑仍然很少。</p></section>
<section><h2>Astra 最后到底改了什么</h2><p>以下六次是能读原文的 Astra。每次先提交四个候选，获得自己候选的验证分后再提交四个，最终只按验证分选择，包括保留 BP 的选项。</p>{changes}<p>独立审查发现，保存的最终程序主要是文本分支强弱调整、热门度基础分校准，以及一次用户向量的公式更新；没有显式的剧情标签、内容分组或电影语义事实进入最终变换。因此，当前结果更接近“在含文本模型上做数值调整”。<strong>这不能证明 Astra 从未读原文，也不能推断它的隐藏思维；但不足以把收益归因于理解了电影情节。</strong></p><p>全文组六次相对同一 BP：五次测试 NDCG 增加，一次保留 BP；相比固定主策略：两次高、四次低。均值差异都不应被写成稳定胜负。第一批四个候选中，一些轨迹会削弱文本分支并降低验证分；后续反馈才促使它尝试增强文本。这也说明“大权重分支”不能直接视为坏分支。</p></section>
<section><h2>完整对照与实验规则</h2>{controls}<p>八候选融合是在同一 SVD＋BP 家族中固定尝试八组系数，再按验证集选择；和 Astra 候选数相同，但不等于计算量、方法范围或反馈轮次相同。</p><p>“八候选数值校准”是在验证阶段看到编辑器经常做文本与偏置缩放后补充的<strong>探索性、事后机制对照</strong>，在测试前固定系数，不向编辑器提供其结果。它不是事先注册的主对照，也不是完全匹配 Astra 的搜索空间。另一个技术澄清是统一接受四个补丁的 JSON 数组或等价单键包装，原始补丁内容不变，没有增加候选额度。</p><p>Astra 共有三种输入：无文本、仅数值文本、数值文本＋可读原文；每种三个训练种子、每个两次独立编辑，合计 18 个全新上下文、144 个候选。允许看完整训练数据和权重、计算训练预测、做直接代数或一次解析拟合；禁止 BP、梯度、迭代训练、自动参数搜索、验证／测试样本和外部资料。没有向编辑器提供预设故障、前轮结论或预期文本优势。</p><p>固定融合操作的是电影 ID 向量与文本结果相加后的有效电影向量；保留 W，通过改变 ID 向量实现融合。各方法限制实际可学习参数的总改变量，最多为原参数范数的 50%，冻结文本不计入可编辑参数。这个限制依赖参数表达方式，因此额外记录了有效电影向量的变化。含文本数值组与全文组使用完全相同的参数表达和预算。</p><details><summary>查看全部十八次编辑结果</summary>{per}</details></section>
<section><h2>成本与可复核性</h2><p>本轮没有重新提取 Llama 向量。三组 BP 分别在 A100 上并行训练，共 {C['bp_training_trials']} 次试验；并行总墙钟约 {C['server_training_jobs']['wall_seconds']:.1f} 秒，单次最长 {C['max_training_trial_wall_seconds']:.1f} 秒，所有训练试验墙钟相加 {C['sum_training_trial_wall_seconds']:.1f} 秒。每条件用相同四组训练设置在 seed42 验证，再固定设置训练另两个种子。GPU 上限为单试验 3,500 秒，实际远低于上限。</p><p>编辑使用 36 次原生 Astra 生成请求，独立结果审查另 1 次；基础设施代理另 2 次。每次调用的 token 和美元账单未暴露，记为未知，不伪造费用。{usage}验证候选评分 {C['editor_validation_wall_seconds']:.2f} 秒，封存重放 {C['freeze_wall_seconds']:.2f} 秒，最终测试 {C['test_reporting_wall_seconds']:.2f} 秒；这些不包含全部 Astra 思考和工具计算。</p><p>144 个候选均有效且完成数值重放，最大参数重现误差约 {Q['portable_max_absolute_error']:.2g}。封存的 {Q['frozen_input_hashes_verified']} 个文件哈希全部保持不变；v5 的 237 个、v6 的 1,014 个旧哈希也未改变。输入 13 项传输校验、18 份输入一致性审计及 58 项测试通过。所选九个 BP 检查点的本地与服务器验证得分差为零。</p><p>完整限制：历史上已使用过的同一 MovieLens 子集和划分，单种模型族，三个训练种子、每组两次编辑；目录内容可见；PCA 压缩会丢失信息，Llama-3 不是专门训练的 embedding 模型。编辑器通过指令限制文件范围，未进行操作系统级隔离。一个未选中的打乱文本训练设置达到轮数上限；所选模型按验证集早停，仍不能声称是全局最优 BP。这轮不足以主张新的推荐算法、Astra 独有能力、冷启动或公平性优势。</p></section>
<section><h2>当前判断与证据</h2><p><strong>加入正确对应的文本，BP 的平均表现更好；Astra 有小幅额外增量，但读原文的可靠收益仍未证实，固定融合的均值仍更高。</strong>这轮不能用来宣称“文本使 WSP 超过经典方法”，也不能说“文本完全没用”。此前论文 PDF 和旧交互解释仍是历史版本，本报告单独保存本轮结论。</p><p><a href="per_case.csv">逐次结果</a> · <a href="condition_means.csv">均值表</a> · <a href="paired_user_intervals.json">条件配对区间</a> · <a href="result_review.json">独立审查</a> · <a href="input_audit.json">输入核验</a> · <a href="costs.json">成本</a> · <a href="editor_artifacts.zip">数值证据包</a></p></section>'''
style='''body{margin:0;background:#f5f3ec;color:#253b32;font:16px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1100px;margin:auto;padding:60px 32px 80px}header{max-width:950px;margin-bottom:48px}h1{font-size:48px;line-height:1.28;letter-spacing:-1px;margin:12px 0 25px}h2{font-size:26px;margin:0 0 16px}.eyebrow{color:#74806e;letter-spacing:2px;font-size:13px}.lead{font-size:21px;line-height:1.7}section{margin:34px 0 50px}p{margin:14px 0}a{color:#236d54;text-underline-offset:3px}strong{color:#164c39}.note{font-size:14px;background:#e9e9df;padding:15px 20px;border-left:3px solid #a58a5b}.scroll{overflow-x:auto;border:1px solid #dddccd;background:#fcfbf7;margin:22px 0}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5;min-width:650px}th,td{padding:13px 14px;text-align:left;border-bottom:1px solid #e0e1d8;vertical-align:top}th{background:#e5e9df;font-weight:600}td{font-variant-numeric:tabular-nums}figure{margin:24px 0}figure img{max-width:100%;height:auto;display:block}summary{cursor:pointer;color:#236d54}details{margin:20px 0}.flow{display:flex;gap:14px;align-items:center;justify-content:center;margin:22px 0}.node{flex:1;text-align:center;padding:16px 12px;border:1px solid #b8c4b8;border-radius:8px;background:#e7eee3}.fixed{background:#e8e7df;border-color:#d0cfc3}.node small{display:block;font-size:12px;color:#617368}.node b{display:block;font-size:14px;margin-top:5px}.bottom{margin-top:10px}.swipe{display:none}@media(max-width:650px){main{padding:30px 18px}h1{font-size:34px}.lead{font-size:18px}body{font-size:15px}h2{font-size:23px}.flow{flex-direction:column}.flow>span{transform:rotate(90deg)}.node{width:90%;box-sizing:border-box}.swipe{display:block;font-size:12px;color:#617368;margin-top:-15px}}'''
(R/'report.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WSP4Rec：Llama 简介特征与 Astra 权重编辑实验</title><style>'+style+'</style><main>'+body+'</main></html>')
print(R/'report.html')
